package com.grdp.studio.softwareintegration;
import com.grdp.studio.softwareintegration.support.*;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.node.ObjectNode;
import tools.jackson.databind.node.ArrayNode;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class EclipseMultiWaterPvtParametersTests {
    private final ObjectMapper mapper=new ObjectMapper();
    private ObjectNode inspection()throws Exception{return (ObjectNode)mapper.readTree(getClass().getResourceAsStream("/eclipse-multi-pvtw-inspection.json"));}
    private ObjectNode request(ObjectNode i,int column){var r=i.path("multiWaterPvtContext").path("regions").path(1);var p=mapper.createObjectNode();String field=new String[]{"REFERENCE_PRESSURE","FORMATION_VOLUME_FACTOR","COMPRESSIBILITY","VISCOSITY","VISCOSIBILITY"}[column];p.put("schemaVersion",EclipseMultiWaterPvtParameters.SCHEMA);p.put("regionNumber",2);p.put("baselineRunId",1);p.put("sourceFile",i.path("caseName").asText());p.put("sourceSha256",i.path("packageFiles").path(0).path("sha256").asText());p.put("lineNumber",r.path("lineNumber").asInt());p.put("field",field);p.put("unit",EclipsePvtwParameters.unitFor("FIELD",field));p.put("originalValue",column==4&&r.path("recordValues").size()==4?0:Double.parseDouble(r.path("recordValues").path(column).asText()));p.put("targetValue",new double[]{4000,1.0506,6e-5,.8,1e-6}[column]);p.set("recordValues",r.path("recordValues").deepCopy());return p;}
    @Test void allFiveAbsoluteWaterValuesBindTheirCompleteSourceRegionAndSurvivePersistence()throws Exception{
        var i=inspection();assertEquals(i.toString(),EclipseDataInspectionValidator.parsePersisted(EclipseDataInspectionValidator.validateAndSerialize(i,mapper)).toString());
        for(int k=0;k<5;k++){var p=request(i,k);assertTrue(EclipseMultiWaterPvtParameters.matchesInspection(p,i));assertTrue(EclipseBatchParameters.scenario(p));var wrong=p.deepCopy();wrong.put("regionNumber",1);assertTrue(EclipseMultiWaterPvtParameters.valid(wrong));assertFalse(EclipseMultiWaterPvtParameters.matchesInspection(wrong,i));wrong.put("regionNumber",3);assertFalse(EclipseMultiWaterPvtParameters.matchesInspection(wrong,i));wrong.put("regionNumber",2);wrong.put("sourceSha256","0".repeat(64));assertFalse(EclipseMultiWaterPvtParameters.matchesInspection(wrong,i));}
    }
    @Test void rejectTypedTargetsDefaultFieldsWrongUnitsAndCrossTableSourceLines()throws Exception{
        var i=inspection();var p=request(i,3);for(var key:new String[]{"regionNumber","targetValue","lineNumber","unit","field"}){var bad=p.deepCopy();bad.put(key,"bad");assertFalse(EclipseMultiWaterPvtParameters.valid(bad));}
        for(double value:new double[]{0,-1,1001,.4}){var bad=p.deepCopy();bad.put("targetValue",value);assertFalse(EclipseMultiWaterPvtParameters.valid(bad));}
        var changed=p.deepCopy();((ArrayNode)changed.path("recordValues")).set(0,mapper.getNodeFactory().stringNode("4499"));assertTrue(EclipseMultiWaterPvtParameters.valid(changed));assertFalse(EclipseMultiWaterPvtParameters.matchesInspection(changed,i));
        for(var fault:new String[]{"cellCount","overlap","default","missing"}){var bad=i.deepCopy();var r=(ObjectNode)bad.path("multiWaterPvtContext").path("regions").path(1);switch(fault){case "cellCount"->r.put("cellCount",8);case "overlap"->r.put("lineNumber",bad.path("multiPvtContext").path("regions").path(1).path("tables").path(1).path("rows").path(0).path("lineNumber").asInt());case "default"->((ArrayNode)r.path("recordValues")).set(4,mapper.getNodeFactory().stringNode("1*"));default->((ArrayNode)r.path("recordValues")).remove(4);}assertFalse(EclipseMultiWaterPvtParameters.validContext(bad.path("multiWaterPvtContext"),bad));assertThrows(IllegalArgumentException.class,()->EclipseDataInspectionValidator.validateAndSerialize(bad,mapper));}
    }
    @Test void pureWaterFullMapRegionsBindFiveFieldsWithoutInventingOilGasTables()throws Exception{
        var i=(ObjectNode)mapper.readTree(getClass().getResourceAsStream("/eclipse-multi-pure-pvtw-inspection.json"));assertFalse(i.has("multiPvtContext"));assertTrue(EclipseMultiWaterPvtParameters.validContext(i.path("multiWaterPvtContext"),i));assertEquals(i.toString(),EclipseDataInspectionValidator.parsePersisted(EclipseDataInspectionValidator.validateAndSerialize(i,mapper)).toString());
        for(int k=0;k<5;k++){var p=request(i,k);p.put("unit",EclipsePvtwParameters.unitFor("METRIC",p.path("field").asText()));p.put("targetValue",new double[]{4000,1.02,6.06e-6,1,1e-6}[k]);assertTrue(EclipseMultiWaterPvtParameters.matchesInspection(p,i));assertTrue(EclipseBatchParameters.scenario(p));}
        for(var fault:new String[]{"cells","phase","region","line"}){var bad=i.deepCopy();var r=(ObjectNode)bad.path("multiWaterPvtContext").path("regions").path(1);switch(fault){case "cells"->r.put("cellCount",119);case "phase"->((ArrayNode)bad.path("phases")).add("OIL");case "region"->r.put("number",1);default->r.put("lineNumber",bad.path("multiWaterPvtContext").path("regions").path(0).path("lineNumber").asInt());}assertFalse(EclipseMultiWaterPvtParameters.validContext(bad.path("multiWaterPvtContext"),bad));assertThrows(IllegalArgumentException.class,()->EclipseDataInspectionValidator.validateAndSerialize(bad,mapper));}
    }
    @Test void omittedCvIsBoundAsOfficialZeroWithoutRewritingOriginalSourceTokens()throws Exception{
        for(var kind:new String[]{"three","pure"}){var i=(ObjectNode)mapper.readTree(getClass().getResourceAsStream("/eclipse-multi-pvtw-default-"+kind+"-inspection.json"));assertTrue(EclipseMultiWaterPvtParameters.validContext(i.path("multiWaterPvtContext"),i));assertEquals(i.toString(),EclipseDataInspectionValidator.parsePersisted(EclipseDataInspectionValidator.validateAndSerialize(i,mapper)).toString());
            for(int k=0;k<5;k++){var p=request(i,k);p.put("schemaVersion",EclipseMultiWaterPvtParameters.SCHEMA2);p.put("unit",EclipsePvtwParameters.unitFor(i.path("unitSystem").asText(),p.path("field").asText()));p.put("targetValue",("pure".equals(kind)?new double[]{4000,1.02,6.06e-6,1,1e-6}:new double[]{4000,1.0506,6e-5,.8,1e-6})[k]);assertTrue(EclipseMultiWaterPvtParameters.matchesInspection(p,i));assertTrue(EclipseBatchParameters.scenario(p));assertEquals(4,p.path("recordValues").size());var expanded=p.deepCopy();((ArrayNode)expanded.path("recordValues")).add("0");assertTrue(EclipseMultiWaterPvtParameters.valid(expanded));assertFalse(EclipseMultiWaterPvtParameters.matchesInspection(expanded,i));p.put("schemaVersion",EclipseMultiWaterPvtParameters.SCHEMA);assertFalse(EclipseMultiWaterPvtParameters.valid(p));}
        }
    }
    @Test void starDefaultsFalseExplicitSchemasAndInventedFifthSourceValuesAreRejected()throws Exception{
        var i=(ObjectNode)mapper.readTree(getClass().getResourceAsStream("/eclipse-multi-pvtw-default-three-inspection.json"));var p=request(i,4);p.put("schemaVersion",EclipseMultiWaterPvtParameters.SCHEMA2);assertTrue(EclipseMultiWaterPvtParameters.matchesInspection(p,i));p.put("originalValue",1e-6);assertFalse(EclipseMultiWaterPvtParameters.valid(p));
        var wrong=i.deepCopy();((ObjectNode)wrong.path("multiWaterPvtContext")).put("schemaVersion","eclipse-multi-water-pvt-context/1");assertThrows(IllegalArgumentException.class,()->EclipseDataInspectionValidator.validateAndSerialize(wrong,mapper));
        var star=i.deepCopy();((ArrayNode)star.path("multiWaterPvtContext").path("regions").path(1).path("recordValues")).set(3,mapper.getNodeFactory().stringNode("1*"));assertThrows(IllegalArgumentException.class,()->EclipseDataInspectionValidator.validateAndSerialize(star,mapper));
        var explicit=inspection();((ObjectNode)explicit.path("multiWaterPvtContext")).put("schemaVersion","eclipse-multi-water-pvt-context/2");assertThrows(IllegalArgumentException.class,()->EclipseDataInspectionValidator.validateAndSerialize(explicit,mapper));
    }
}
